// android/ is generated by `npx cap add android` and gitignored. Permissions,
// the tracking service and the receivers come from the mile-native plugin's own
// manifest (merged automatically); this only makes the app single-task so a
// notification tap returns to the running app instead of a second copy.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const manifestPath = join(root, "android", "app", "src", "main", "AndroidManifest.xml");
if (!existsSync(manifestPath)) {
  console.error("android/ not found - run `npx cap add android` first.");
  process.exit(1);
}
let xml = readFileSync(manifestPath, "utf8");
if (!xml.includes('android:launchMode="singleTask"')) {
  xml = xml.replace(/<activity\b/, '<activity android:launchMode="singleTask"');
  writeFileSync(manifestPath, xml);
  console.log("AndroidManifest.xml: launchMode=singleTask");
} else {
  console.log("AndroidManifest.xml already patched.");
}
